#!/usr/bin/env python3
"""Companion-protocol vectors for the radio settings (MeshCore v1.18, commit 81dbae5).

Written from the firmware itself, `examples/companion_radio/MyMesh.cpp` at
https://github.com/meshcore-dev/MeshCore/blob/81dbae5/examples/companion_radio/MyMesh.cpp
(the line of each handler is given), with Python's struct: nothing is shared with the Rust
code. Regenerate with:
    python3 -I testdata/meshcore/settings.py > testdata/meshcore/settings.toml
"""
import struct


def out(kind, name, frame, source, **fields):
    print(f"[[{kind}]]")
    print(f'name = "{name}"')
    print(f'hex = "{frame.hex()}"')
    for k, v in fields.items():
        print(f"{k} = {v!r}".replace("'", '"') if isinstance(v, str) else f"{k} = {str(v).lower()}")
    print(f'source = "{source}"')
    print()


def main():
    print("# Radio settings, companion protocol v1.18 (81dbae5). Generated by settings.py: do not edit.\n")
    # CMD_SET_RADIO_PARAMS (11), MyMesh.cpp#L1424: freq kHz u32, bw Hz u32, sf, cr, repeat.
    out("command", "set-radio-params", struct.pack("<BIIBBB", 11, 869_618, 62_500, 8, 8, 0),
        "MyMesh.cpp#L1424", freq_khz=869_618, bw_hz=62_500, sf=8, cr=8, repeat=False)
    # CMD_SET_ADVERT_LATLON (14), MyMesh.cpp#L1266: lat, lon i32 × 1e6.
    out("command", "set-advert-latlon", struct.pack("<Bii", 14, 45_000_000, -6_500_000),
        "MyMesh.cpp#L1266", lat_e6=45_000_000, lon_e6=-6_500_000)
    # CMD_REBOOT (19), MyMesh.cpp#L1512: "reboot".
    out("command", "reboot", bytes([19]) + b"reboot", "MyMesh.cpp#L1512")
    # CMD_SET_DEVICE_PIN (37), MyMesh.cpp#L1839: pin u32, 0 or 100000..999999.
    out("command", "set-device-pin", struct.pack("<BI", 37, 123_456), "MyMesh.cpp#L1839", pin=123_456)
    # CMD_SET_OTHER_PARAMS (38), MyMesh.cpp#L1488: manual_add, telemetry, advert_loc_policy, multi_acks.
    telemetry = (0 << 4) | (1 << 2) | 2   # env nobody, location per contact, base everyone
    out("command", "set-other-params", bytes([38, 1, telemetry, 1, 2]), "MyMesh.cpp#L1488",
        manual_add=True, telemetry=telemetry, advert_loc_policy=1, multi_acks=2)
    # CMD_GET_CUSTOM_VARS (40), MyMesh.cpp#L1853; CMD_SET_CUSTOM_VAR (41), MyMesh.cpp#L1867.
    out("command", "get-custom-vars", bytes([40]), "MyMesh.cpp#L1853")
    out("command", "set-custom-var", bytes([41]) + b"gps:1", "MyMesh.cpp#L1867", var="gps", value="1")
    # CMD_SET_AUTOADD_CONFIG (58), CMD_GET_AUTOADD_CONFIG (59), MyMesh.cpp#L2023-L2035.
    out("command", "set-autoadd-config", bytes([58, 0x02 | 0x01, 3]), "MyMesh.cpp#L2023", mask=3, max_hops=3)
    out("command", "get-autoadd-config", bytes([59]), "MyMesh.cpp#L2030")

    # RESP_CODE_CUSTOM_VARS (21): "name:value" pairs joined by commas, no NUL.
    out("response", "custom-vars", bytes([21]) + b"gps:1,gps_interval:300", "MyMesh.cpp#L1853",
        text="gps:1,gps_interval:300")
    out("response", "custom-vars-none", bytes([21]), "MyMesh.cpp#L1853", text="")
    # RESP_CODE_AUTOADD_CONFIG (25): mask, max_hops.
    out("response", "autoadd-config", bytes([25, 0x02 | 0x04, 2]), "MyMesh.cpp#L2030", mask=6, max_hops=2)
    # RESP_CODE_SELF_INFO (5), MyMesh.cpp#L1085-L1117: adv_type, tx, max tx, key, lat, lon,
    # multi_acks, advert_loc_policy, telemetry bits, manual_add, freq kHz, bw Hz, sf, cr, name.
    key = bytes(range(0x10, 0x30))
    frame = (bytes([5, 1, 14, 22]) + key + struct.pack("<ii", 45_123_456, -6_543_210)
             + bytes([1, 1, telemetry, 1]) + struct.pack("<IIBB", 869_618, 62_500, 8, 8) + b"lichen-test")
    out("response", "self-info-prefs", frame, "MyMesh.cpp#L1085", tx_power=14, max_tx_power=22,
        lat_e6=45_123_456, lon_e6=-6_543_210, multi_acks=1, advert_loc_policy=1,
        telemetry=telemetry, manual_add=True, freq_khz=869_618, bw_hz=62_500, sf=8, cr=8,
        node_name="lichen-test")


main()
